package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.cli.OptionBuilder.create(String)
 */
public class OptionBuilder_create_TriageGen1Test {

    @Test
    public void testCreateWithValidString() {
        // Arrange
        String opt = "a";
        String description = "test description";
        String longopt = "long-opt";
        boolean required = true;
        boolean optionalArg = false;
        int numberOfArgs = 1;
        Object type = String.class;
        char valuesep = ',';
        String argName = "argName";

        // Act
        OptionBuilder.withDescription(description)
                     .withLongOpt(longopt)
                     .isRequired(required)
                     .hasArg(optionalArg)
                     .hasArgs(numberOfArgs)
                     .withType(type)
                     .withValueSeparator(valuesep)
                     .withArgName(argName);

        Option option = OptionBuilder.create(opt);

        // Assert
        assertNotNull(option);
        assertEquals(opt, option.getOpt());
        assertEquals(description, option.getDescription());
        assertEquals(longopt, option.getLongOpt());
        assertEquals(required, option.isRequired());
        assertEquals(optionalArg, option.hasArg());
        assertEquals(numberOfArgs, option.getArgCount());
        assertEquals(type, option.getType());
        assertEquals(valuesep, option.getValueSeparator());
        assertEquals(argName, option.getArgName());
    }

    @Test
    public void testCreateWithMinimalProperties() {
        // Arrange
        String opt = "b";

        // Act
        Option option = OptionBuilder.create(opt);

        // Assert
        assertNotNull(option);
        assertEquals(opt, option.getOpt());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateWithNullString() {
        // Act
        OptionBuilder.create(null);
    }

    @Test
    public void testResetAfterCreate() {
        // Arrange
        OptionBuilder.withDescription("first");
        OptionBuilder.create("a");

        // Act
        // The create method calls OptionBuilder.reset() internally.
        // We verify that subsequent calls don't carry over "first"
        OptionBuilder.withDescription("second");
        Option option = OptionBuilder.create("b");

        // Assert
        assertEquals("second", option.getDescription());

        // Verify that a fresh creation doesn't have the "first" description
        OptionBuilder.reset();
        Option option2 = OptionBuilder.create("c");
        assertNull(option2.getDescription());
    }

    @Test
    public void testCreateWithEmptyString() {
        // Arrange
        String opt = "";

        // Act
        Option option = OptionBuilder.create(opt);

        // Assert
        assertNotNull(option);
        assertEquals("", option.getOpt());
    }

    @Test
    public void testCreateWithVariousArgTypes() {
        // Test hasOptionalArgs
        OptionBuilder.hasOptionalArgs(2);
        Option opt1 = OptionBuilder.create("o");
        assertEquals(2, opt1.getArgCount());

        OptionBuilder.reset();

        // Test hasArgs
        OptionBuilder.hasArgs(3);
        Option opt2 = OptionBuilder.create("h");
        assertEquals(3, opt2.getArgCount());
    }
}
